test('the one-month claims about 2008-09 are printed exactly when the books bear them out', async ({ page }) => {
  const c08 = EVIDENCE.crisis_2008
  const depths = (['5pct', '10pct', '15pct', '20pct'] as const).map((k) => c08[k])
  const ahead = depths.flatMap((r) => r.books.filter((b) => b.terminal_without_best !== undefined).map((b) => ({ r, b })))
  const oneMonth =
    ahead.length > 0 &&
    ahead.every((x) => x.b.terminal_without_best! < x.r.unhedged.terminal && x.r.best_entry === ahead[0]!.r.best_entry)
  const detail = page.locator('#pitch-verdict-detail')
  if (oneMonth) await expect(detail).toContainText(`every one on the roll bought ${ahead[0]!.r.best_entry} and behind without it`)
  else await expect(detail).not.toContainText('and behind without it')
  const off = Object.values(c08.spread_guard_off.depths).every((d) =>
    d.books.every((b) => b.terminal_without_best === undefined || b.terminal_without_best < d.unhedged.terminal),
  )
  const claim = 'without it, every one of those books ends behind unhedged'
  if (off) await expect(page.locator('#pitch-2008')).toContainText(claim)
  else await expect(page.locator('#pitch-2008')).not.toContainText(claim)
})

test('counts derived from the standalone table match it', async ({ page }) => {
  const spy = EVIDENCE.SPY.standalone
  const periods = Object.values(spy['20pct_4w_hold']!.by_period)
  await expect(page.locator('#pitch-standalone')).toContainText(
    `winners fall in ${periods.filter((v) => v.hits > 0).length} of ${periods.length} periods`,
  )
  const years = Number(EVIDENCE.panels.SPY.last.slice(0, 4)) - Number(EVIDENCE.panels.SPY.first.slice(0, 4)) + 1
  await expect(page.locator('#pitch-verdict-detail')).toContainText(`${years} years of quotes cannot tell`)
  const most = Math.max(...Object.values(spy).map((s) => s.n_rolls))
  await expect(page.locator('#pitch-caveats')).toContainText(`not on the up to ${most} rolls per rule`)
  const sold = Object.entries(spy).filter(([r]) => !r.includes('_4w_hold')).map(([, s]) => s)
  const itm = sold.reduce((k, s) => k + s.exits_at_intrinsic_itm, 0)
  const rolls = sold.reduce((k, s) => k + s.n_rolls, 0)
  await expect(page.locator('#pitch-method')).toContainText(`on ${itm} in-the-money exits of ${n(rolls)} sold rolls`)
  // The intrinsic credits are mostly strikes the panel's 1.02 band dropped,
  // not refused bids, and the page must say which way that biases the result.
  const beyond = sold.reduce((k, s) => k + s.exits_beyond_panel, 0)
  // "21 of those" when it is all of them reads as a subset.
  await expect(page.locator('#pitch-method')).toContainText(
    beyond === itm ? `None of those ${beyond} is a refused bid: the panel` : `${beyond} of those in-the-money exits are not refused bids: the panel`,
  )
  await expect(page.locator('#pitch-method')).toContainText('biased against the put')
  // A no-bid sale out of the money is credited zero; those are counted too.
  const otm = sold.reduce((k, s) => k + s.exits_at_intrinsic - s.exits_at_intrinsic_itm, 0)
  if (otm > 0)
    await expect(page.locator('#pitch-method')).toContainText(`(and ${otm} out-of-the-money sales with no bid were credited zero)`)
  const best = Object.entries(spy)
    .filter(([r, s]) => !r.includes('_4w_hold') && s.best_roll_beyond_panel)
    .map(([r]) => ruleLabel(r))
  // Which rules' Best column the understated exits reach, in its own sentence.
  if (best.length > 1)
    await expect(page.locator('#pitch-method')).toContainText(
      `The best rolls of ${best.length} rules are among these exits (${best.join('; ')}), so their Best figures are understated.`,
    )
  else if (best.length === 1)
    await expect(page.locator('#pitch-method')).toContainText(`The best roll of one rule is among these exits (${best[0]})`)
  // Rolls complete at different dates, so the range is the earliest and latest
  // last exit, whatever order the rules come in.
  const lastExits = Object.values(spy).map((s) => s.last_exit)
  const lo = lastExits.reduce((a, b) => (b < a ? b : a))
  const hi = lastExits.reduce((a, b) => (b > a ? b : a))
  await expect(page.locator('#pitch-method')).toContainText(`rules’ last exits fall between ${lo} and ${hi}`)
})

test('the timing correction is said to cover the mean-return objective only', async ({ page }) => {
  // The Benjamini–Hochberg pass and the raw-p count run over the mean-return
  // p-values only; the growth objective has one p (its pick's). A bare "0
  // survived" would read as covering the hedge objective too.
  const dg = EVIDENCE.timing.dg
  await expect(page.getByTestId('pitch-verdict')).toContainText(
    `sample on mean return (on hedge growth only the in-sample pick was tested, p = ${dg.oos_p.toFixed(3)}`,
  )
  await expect(page.locator('#pitch-verdict-detail')).toContainText('The multiple-testing correction covers the mean-return objective only')
  const timing = page.locator('#pitch-timing')
  await expect(timing).toContainText(
    `${fmtFixed(EVIDENCE.timing.roi_diff.spearman_is_oos)} on mean return and ${fmtFixed(dg.spearman_is_oos)} on growth`,
  )
  await expect(timing).toContainText(
    `${EVIDENCE.timing.bh.p_below_05} of ${EVIDENCE.timing.bh.tested} mean-return differences have a raw p below 0.05`,
  )
  // Both comparisons are derived on the page; a wrong chance count or a
  // ratio against the FDR instead of the first BH step would mislead.
  const bh = EVIDENCE.timing.bh
  await expect(timing).toContainText(`about the ${Math.round(bh.tested * 0.05)} that chance would give`)
  const bestNotCrisis = Math.min(...bh.smallest_p.filter((x) => x.gate === 'regime=not_crisis').map((x) => x.oos_p))
  await expect(timing).toContainText(`about ${Math.round(bestNotCrisis / (bh.fdr / bh.tested))}× the first BH`)
})

test('the fills step says the spread cap guards buys only, and how long a sold put still runs', async ({ page }) => {
  // OptionsDxQuoteSource.mark has no spread check: a sale or daily mark takes
  // any bid above zero. Saying the cap is symmetric overstates the guard.
  const method = page.locator('#pitch-method')
  await expect(method).toContainText('the 50% spread cap applies to buys, not to sales or marks')
  // A sold put exits after a 28-day hold, so it still has entry DTE - 28 to run.
  const spy = EVIDENCE.SPY.standalone
  const left = (r: string) => Math.round(spy[r]!.median_dte - 28)
  await expect(method).toContainText(
    `time value such a put still has with about ${left('5pct_8w_sell4w')} or ${left('5pct_12w_sell4w')} days to run at the median`,
  )
})

test('dates in the prose do not break at their hyphens on a phone', async ({ page }) => {
  // "2020-02-" / "21" misreads on a page whose evidence turns on single dates.
  await page.setViewportSize({ width: 390, height: 844 })
  const lede = page.getByTestId('pitch-verdict')
  for (const d of [EVIDENCE.panels.SPY.first, EVIDENCE.panels.SPY.last]) {
    await expect(lede.locator('.pl-date', { hasText: d }).first()).toBeVisible()
  }
  // Every date the page wraps is kept whole: nowrap, and one line box (a
  // wrapped span has more than one client rect).
  const dates = await page.locator('.pl-date').evaluateAll((els) =>
    els.map((e) => ({ text: e.textContent, ws: getComputedStyle(e).whiteSpace, rects: e.getClientRects().length })),
  )
  // The verdict-flips table is where the dates are the evidence: each as-of
  // cell is a kept-whole date, so the check below covers it.
  await expect(page.getByTestId('pitch-flips').locator('tbody tr td:first-child .pl-date')).toHaveCount(
    LIVE.spy_verdicts.length,
  )
  expect(dates.length).toBeGreaterThan(20)
  for (const d of dates) {
    expect(d.text).toMatch(/^\d{4}-\d{2}-\d{2}$/)
    expect(d, String(d.text)).toEqual({ text: d.text, ws: 'nowrap', rects: 1 })
  }
})

